import type { SwitchProps } from "./switch.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import * as RadixSwitch from "@radix-ui/react-switch";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Switch";

// Generate child element class names for the component, should match available style slots
export const SwitchClasses = {
  root: "exp-textura_switch",
  thumb: "exp-textura_switch_thumb",
  track: "exp-textura_switch_track",
  onIcon: "exp-textura_switch_on_icon",
  offIcon: "exp-textura_switch_off_icon",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    track: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.background.enabled,
      borderColor: theme.inputSelect.switch.off.critical.color.border.enabled,
    },
    trackHover: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.background.hover,
      borderColor: theme.inputSelect.switch.off.critical.color.border.hover,
    },
    trackPressed: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.background.pressed,
      borderColor: theme.inputSelect.switch.off.critical.color.border.pressed,
    },
    trackDisabled: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.background.disabled,
      borderColor: theme.inputSelect.switch.off.critical.color.border.disabled,
    },
    checkedTrack: {
      backgroundColor: theme.inputSelect.switch.on.critical.color.background.enabled,
      borderColor: theme.inputSelect.switch.on.critical.color.border.enabled,
    },
    checkedTrackHover: {
      backgroundColor: theme.inputSelect.switch.on.critical.color.background.hover,
      borderColor: theme.inputSelect.switch.on.critical.color.border.hover,
    },
    checkedTrackPressed: {
      backgroundColor: theme.inputSelect.switch.on.critical.color.background.pressed,
      borderColor: theme.inputSelect.switch.on.critical.color.border.pressed,
    },
    checkedTrackDisabled: {
      backgroundColor: theme.inputSelect.switch.on.critical.color.background.disabled,
      borderColor: theme.inputSelect.switch.on.critical.color.border.disabled,
    },
    thumb: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.border.enabled,
    },
    thumbHover: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.content.hover,
    },
    thumbPressed: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.content.pressed,
    },
    thumbDisabled: {
      backgroundColor: theme.inputSelect.switch.off.critical.color.content.disabled,
    },
    checkedThumb: {
      backgroundColor: theme.color.content.inverseStrong,
    },
    checkedThumbHover: {
      backgroundColor: theme.color.content.inverseStrong,
    },
    checkedThumbPressed: {
      backgroundColor: theme.color.content.inverseStrong,
    },
    checkedThumbDisabled: {
      backgroundColor: theme.color.content.inverseStrong,
    },
    onIcon: {
      color: theme.inputSelect.switch.on.critical.color.background.enabled,
    },
    onIconHover: {
      color: theme.inputSelect.switch.on.critical.color.background.hover,
    },
    onIconPressed: {
      color: theme.inputSelect.switch.on.critical.color.background.pressed,
    },
    onIconDisabled: {
      color: theme.inputSelect.switch.on.critical.color.background.disabled,
    },
    offIcon: {
      color: theme.inputSelect.switch.off.critical.color.content.enabled,
    },
    offIconHover: {
      color: theme.inputSelect.switch.off.critical.color.content.hover,
    },
    offIconPressed: {
      color: theme.inputSelect.switch.off.critical.color.content.pressed,
    },
    offIconDisabled: {
      color: theme.inputSelect.switch.off.critical.color.content.disabled,
    },
  },
  inverse: {
    track: {
      backgroundColor: theme.inputSelect.switch.off.inverse.color.background.enabled,
      borderColor: theme.inputSelect.switch.off.inverse.color.border.enabled,
    },
    trackHover: {
      backgroundColor: theme.inputSelect.switch.off.inverse.color.background.hover,
      borderColor: theme.inputSelect.switch.off.inverse.color.border.hover,
    },
    trackPressed: {
      backgroundColor: theme.inputSelect.switch.off.inverse.color.background.pressed,
      borderColor: theme.inputSelect.switch.off.inverse.color.border.pressed,
    },
    trackDisabled: {
      backgroundColor: theme.inputSelect.switch.off.inverse.color.background.disabled,
      borderColor: theme.inputSelect.switch.off.inverse.color.border.disabled,
    },
    checkedTrack: {
      backgroundColor: theme.inputSelect.switch.on.inverse.color.background.enabled,
      borderColor: theme.inputSelect.switch.on.inverse.color.border.enabled,
    },
    checkedTrackHover: {
      backgroundColor: theme.inputSelect.switch.on.inverse.color.background.hover,
      borderColor: theme.inputSelect.switch.on.inverse.color.border.hover,
    },
    checkedTrackPressed: {
      backgroundColor: theme.inputSelect.switch.on.inverse.color.background.pressed,
      borderColor: theme.inputSelect.switch.on.inverse.color.border.pressed,
    },
    checkedTrackDisabled: {
      backgroundColor: theme.inputSelect.switch.on.inverse.color.background.disabled,
      borderColor: theme.inputSelect.switch.on.inverse.color.border.disabled,
    },
    thumb: {
      backgroundColor: theme.color.transparency.white[80],
    },
    thumbHover: {
      backgroundColor: theme.color.neutral.white,
    },
    thumbPressed: {
      backgroundColor: theme.color.neutral.white,
    },
    thumbDisabled: {
      backgroundColor: theme.color.transparency.white[30],
    },
    checkedThumb: {
      backgroundColor: theme.color.transparency.black[80],
    },
    checkedThumbHover: {
      backgroundColor: theme.color.neutral.white,
    },
    checkedThumbPressed: {
      backgroundColor: theme.color.neutral.white,
    },
    checkedThumbDisabled: {
      backgroundColor: theme.color.transparency.black[30],
    },
    onIcon: {
      color: theme.inputSelect.switch.on.inverse.color.content.enabled,
    },
    onIconHover: {
      color: theme.inputSelect.switch.on.inverse.color.content.hover,
    },
    onIconPressed: {
      color: theme.inputSelect.switch.on.inverse.color.content.pressed,
    },
    onIconDisabled: {
      color: theme.inputSelect.switch.on.inverse.color.background.disabled,
    },
    offIcon: {
      color: theme.inputSelect.switch.off.inverse.color.content.enabled,
    },
    offIconHover: {
      color: theme.inputSelect.switch.off.inverse.color.content.hover,
    },
    offIconPressed: {
      color: theme.inputSelect.switch.off.inverse.color.content.pressed,
    },
    offIconDisabled: {
      color: theme.inputSelect.switch.off.inverse.color.content.disabled,
    },
  },
});

const generateStyles = (props: SwitchProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SwitchProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    all: "unset",
    position: "relative",
    WebkitTapHighlightColor: "rgba(0, 0, 0, 0)",
    width: theme.toRem(theme.spacing[32]),
    height: theme.toRem(20),
    borderRadius: theme.toRem(theme.border.radius.lg),
    padding: theme.border.width.sm,

    "&:focus-visible": {
      [`& .${SwitchClasses.track}`]: {
        boxShadow: "none",
      },
      ...styleSlots?.focus,
    },

    "&:hover:not([disabled])": {
      cursor: "pointer",
      [`& .${SwitchClasses.track}`]: {
        backgroundColor: theme.inputSelect.switch.off.default.color.background.hover,
        borderColor: theme.inputSelect.switch.off.default.color.background.hover,
        ...styleSlots?.trackHover,
      },
      [`& .${SwitchClasses.thumb}`]: {
        backgroundColor: theme.inputSelect.switch.off.default.color.content.hover,
        ...styleSlots?.thumbHover,
      },
      [`& .${SwitchClasses.onIcon}`]: {
        color: theme.inputSelect.switch.on.default.color.background.hover,
        ...styleSlots?.onIconHover,
      },
      [`& .${SwitchClasses.offIcon}`]: {
        color: theme.inputSelect.switch.off.default.color.content.hover,
        ...styleSlots?.offIconHover,
      },
      ...styleSlots?.hover,
    },

    "&:active:not([disabled])": {
      [`& .${SwitchClasses.track}`]: {
        backgroundColor: theme.inputSelect.switch.off.default.color.background.pressed,
        borderColor: theme.inputSelect.switch.off.default.color.background.pressed,
        ...styleSlots?.trackPressed,
      },
      [`& .${SwitchClasses.thumb}`]: {
        backgroundColor: theme.inputSelect.switch.off.default.color.content.pressed,
        ...styleSlots?.thumbPressed,
      },
      [`& .${SwitchClasses.onIcon}`]: {
        color: theme.inputSelect.switch.on.default.color.background.pressed,
        ...styleSlots?.onIconPressed,
      },
      [`& .${SwitchClasses.offIcon}`]: {
        color: theme.inputSelect.switch.off.default.color.content.pressed,
        ...styleSlots?.offIconPressed,
      },
      ...styleSlots?.pressed,
    },

    [`&[data-state=checked]`]: {
      [`& .${SwitchClasses.track}`]: {
        backgroundColor: theme.inputSelect.switch.on.default.color.background.enabled,
        borderColor: theme.inputSelect.switch.on.default.color.background.enabled,
        ...styleSlots?.checkedTrack,
      },

      [`& .${SwitchClasses.thumb}`]: {
        backgroundColor: theme.color.neutral.white,
        transform: `translateX(15px) scale(1.33)`,
        ":dir(rtl)": {
          transform: `translateX(-15px) scale(1.33)`,
        },
        ...styleSlots?.checkedThumb,
      },

      "&:hover:not([disabled])": {
        [`& .${SwitchClasses.track}`]: {
          backgroundColor: theme.inputSelect.switch.on.default.color.background.hover,
          borderColor: theme.inputSelect.switch.on.default.color.background.hover,
          ...styleSlots?.checkedTrackHover,
        },
        [`& .${SwitchClasses.thumb}`]: {
          backgroundColor: theme.color.neutral.white,
          ...styleSlots?.checkedThumbHover,
        },
        ...styleSlots?.checkedHover,
      },

      "&:active:not([disabled])": {
        [`& .${SwitchClasses.track}`]: {
          backgroundColor: theme.inputSelect.switch.on.default.color.background.pressed,
          borderColor: theme.inputSelect.switch.on.default.color.background.pressed,
          ...styleSlots?.checkedTrackPressed,
        },
        [`& .${SwitchClasses.thumb}`]: {
          backgroundColor: theme.color.neutral.white,
          ...styleSlots?.checkedThumbPressed,
        },
        ...styleSlots?.checkedPressed,
      },

      ...styleSlots?.checked,
    },

    [`&[data-disabled]`]: {
      cursor: "not-allowed",
      [`& .${SwitchClasses.track}`]: {
        backgroundColor: theme.inputSelect.switch.off.default.color.background.disabled,
        borderColor: theme.inputSelect.switch.off.default.color.background.disabled,
        ...styleSlots?.trackDisabled,
      },
      [`& .${SwitchClasses.thumb}`]: {
        backgroundColor: theme.inputSelect.switch.off.default.color.content.disabled,
        ...styleSlots?.thumbDisabled,
      },
      "&[data-state=checked]": {
        [`& .${SwitchClasses.track}`]: {
          backgroundColor: theme.inputSelect.switch.on.default.color.background.disabled,
          borderColor: theme.inputSelect.switch.on.default.color.background.disabled,
          ...styleSlots?.checkedTrackDisabled,
        },
        [`& .${SwitchClasses.thumb}`]: {
          backgroundColor: theme.color.neutral.white,
          ...styleSlots?.checkedThumbDisabled,
        },
      },
      [`& .${SwitchClasses.onIcon}`]: {
        color: theme.inputSelect.switch.on.default.color.background.disabled,
        ...styleSlots?.onIconDisabled,
      },
      [`& .${SwitchClasses.offIcon}`]: {
        color: theme.inputSelect.switch.off.default.color.content.disabled,
        ...styleSlots?.offIconDisabled,
      },
      ...styleSlots?.disabled,
    },

    [`& .${SwitchClasses.track}`]: {
      position: "absolute",
      boxSizing: "border-box",
      backgroundColor: theme.inputSelect.switch.off.default.color.background.enabled,
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.inputSelect.switch.off.default.color.content.enabled}`,
      borderRadius: theme.toRem(theme.border.radius.lg),
      height: "100%",
      width: "100%",
      top: "50%",
      left: "50%",
      transform: "translate(-50%, -50%)",
      display: "flex",
      justifyContent: "end",
      alignItems: "center",
      ...styleSlots?.track,
    },

    [`& .${SwitchClasses.thumb}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      boxSizing: "border-box",
      width: theme.toRem(theme.spacing[12]),
      height: theme.toRem(theme.spacing[12]),
      backgroundColor: theme.inputSelect.switch.off.default.color.content.enabled,
      borderRadius: theme.toRem(theme.border.radius.lg),
      transform: `translateX(1px)`,
      transition: "transform 100ms cubic-bezier(0.22, 0.61, 0.36, 1)",
      willChange: "transform",
      ":dir(rtl)": {
        transform: `translateX(-1px)`,
      },
      ...styleSlots?.thumb,
    },

    [`& .${SwitchClasses.onIcon}`]: {
      position: "absolute",
      display: "none",
      width: theme.toRem(theme.spacing[12]),
      height: theme.toRem(theme.spacing[12]),
      color: theme.inputSelect.switch.on.default.color.background.enabled,
      left: theme.toRem(theme.spacing[16]),
      top: "50%",
      transform: "translateY(-50%)",
      pointerEvents: "none",
      ...styleSlots?.onIcon,
    },

    [`& .${SwitchClasses.offIcon}`]: {
      position: "absolute",
      display: "flex",
      width: theme.toRem(theme.spacing[8]),
      height: theme.toRem(theme.spacing[8]),
      color: theme.inputSelect.switch.off.default.color.content.enabled,
      left: theme.toRem(18),
      top: "50%",
      transform: "translateY(-50%)",
      pointerEvents: "none",
      ...styleSlots?.offIcon,
    },

    [`&[data-state=checked] .${SwitchClasses.onIcon}`]: {
      display: "flex",
    },

    [`&[data-state=checked] .${SwitchClasses.offIcon}`]: {
      display: "none",
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSwitch = styled(RadixSwitch.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SwitchProps>((props) => generateStyles(props));
